import express from 'express';
import multer from 'multer';
import path from 'node:path';
import { writeFile } from 'node:fs/promises';

const app = express();
const upload = multer();

app.post('/upload', upload.single('file'), async (req, res) => {
  if (!req.file || typeof req.body.filename !== 'string') {
    return res.status(400).send('Missing file or filename');
  }

  const destination = path.join('/srv/uploads', req.body.filename);
  await writeFile(destination, req.file.buffer);
  return res.status(201).send('Uploaded');
});

